#!/usr/bin/env python3
from __future__ import annotations
import json
from pathlib import Path
P=Path('usmle/batch_specs_1401_1500/02_q1426_q1450_author_20260908_schema_repaired.json')

def ev(q,key,sid,loc,r):
 return [{'claim_id':f'Q{q}-{L}','option':L,'claim_locator':f'explanation.distractor_explanations.{L}','claim':r[L],'source_ids':[sid],'direct_or_inference':'direct' if L==key else 'inference','source_locator':loc,'item_specific_application':'Keyed target/mechanism is directly supported by the cited source; distractor rejection uses that mechanism plus stipulated experimental conditions.'} for L in 'ABCDE']
def qa(alt,res): return {'key_correctness':'PASS','all_options_review':'PASS','single_best_answer':'PASS','second_answer_attack':{'option':alt,'resolution':res,'status':'PASS'},'hidden_assumptions':'PASS','numerical_claims':'PASS — no invented dose, cutoff, response percentage, trial result, or empirical item statistic.','fabricated_distractors':'PASS','source_identity_setid_url_locator':'PASS','currentness':'PASS — current DailyMed SetID page reverified 2026-09-10; no unsupported revision date asserted.','blueprint':'PASS','difficulty':'Author estimate only','rationale':'PASS A-E','educational_objective':'PASS','adversarial_second_pass':'PASS','technical_hash_gate':'PENDING','unresolved_content_defects':[]}
def make(q,drug,system,disc,vig,lead,opts,key,construct,keyexp,rats,eo,title,setid,loc,alt,res):
 sid=f'Q{q}-LABEL'
 return {'num':q,'drug':drug,'country_scope':'United States','status':'AUTHOR_QA_PASS_PENDING_TECHNICAL_FREEZE_AND_INDEPENDENT_AUDIT','blueprint':{'primary_system':system,'primary_competency':'Medical Knowledge: Applying Foundational Science Concepts','disciplines':disc,'official_outline_path':[system],'specification_source_id':'USMLE-SPEC'},'item':{'vignette':vig,'lead_in':lead,'options':opts,'intended_key':key,'tested_construct':construct,'difficulty':'moderate-hard','difficulty_basis':'Author estimate based on mechanistic discrimination; no empirical calibration claimed.'},'explanation':{'key_explanation':keyexp,'distractor_explanations':rats,'educational_objective':eo},'sources':[{'source_id':sid,'title':title,'agency':'Manufacturer prescribing information hosted by NLM DailyMed','url':f'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid={setid}','setid':setid,'source_section_date':None,'date_basis':'Current DailyMed SetID page and cited mechanism section reverified 2026-09-10; no revision date inferred.','retrieved_at':'2026-09-10','section_locator':loc,'source_page_sha256':None,'cited_section_sha256':None,'hash_status':'PENDING_DETERMINISTIC_REFETCH_AND_HASH'}],'evidence_map':ev(q,key,sid,loc,rats),'author_qa':qa(alt,res)}
def main():
 b=json.loads(P.read_text()); xs={x['num']:x for x in b['items']}
 for q,d in {1434:'daridorexant',1435:'sulbactam/durlobactam',1440:'sparsentan',1443:'revumenib'}.items(): assert xs[q]['drug']==d
 repl={}
 repl[1434]=make(1434,'zolbetuximab-clzb','Gastrointestinal System',['Pharmacology','Immunology'],'CLDN18.2-positive gastric-cancer cells are exposed to zolbetuximab-clzb in the presence of immune effector cells and complement. Tumor-cell lysis increases through both antibody-dependent and complement-dependent pathways.','Which direct target best explains this cytotoxicity?',{'A':'HER2','B':'PD-1','C':'VEGF-A','D':'Claudin 18.2','E':'EGFR'},'D','CLDN18.2-directed cytolytic antibody with ADCC and CDC','Zolbetuximab-clzb is a CLDN18.2-directed cytolytic antibody that depletes CLDN18.2-positive cells through antibody-dependent cellular cytotoxicity and complement-dependent cytotoxicity.',{'A':'HER2-directed antibodies use a different tumor antigen.','B':'PD-1 blockade alters T-cell checkpoints rather than directly targeting the tumor-cell junctional antigen described.','C':'VEGF-A neutralization is antiangiogenic and does not explain CLDN18.2-dependent lysis.','D':'Correct. Zolbetuximab-clzb targets CLDN18.2 and mediates ADCC and CDC.','E':'EGFR targeting does not match the antigen-dependent cytolysis in the stem.'},'Recognize a tumor-antigen-directed antibody mechanism from CLDN18.2-dependent ADCC and CDC.','VYLOY- zolbetuximab injection, powder, for suspension','e7695a21-abb6-47ac-93f8-0ece5a9c4409','12.1 Mechanism of Action','A','Several monoclonal antibodies can trigger immune-mediated tumor killing, but the stipulated CLDN18.2 dependence uniquely selects zolbetuximab.')
 repl[1435]=make(1435,'ensifentrine','Respiratory & Renal/Urinary Systems',['Pharmacology','Biochemistry'],'Airway smooth-muscle cells are exposed to ensifentrine. Intracellular cyclic nucleotide concentrations rise while assays show inhibition of two phosphodiesterase families rather than beta-adrenergic receptor activation.','Which enzyme pair is directly inhibited?',{'A':'PDE1 and PDE2','B':'PDE4 and PDE5','C':'PDE5 and PDE6','D':'PDE2 and PDE7','E':'PDE3 and PDE4'},'E','Dual PDE3/PDE4 inhibition','Ensifentrine inhibits PDE3 and PDE4. PDE3 hydrolyzes cAMP and can hydrolyze cGMP, whereas PDE4 hydrolyzes cAMP; inhibition increases intracellular cyclic nucleotide signaling.',{'A':'These are not the phosphodiesterase families identified for ensifentrine.','B':'PDE5 is not part of the documented target pair.','C':'PDE5/PDE6 inhibition is a different pharmacologic profile.','D':'PDE2/PDE7 inhibition does not match the labeled mechanism.','E':'Correct. Ensifentrine directly inhibits PDE3 and PDE4.'},'Differentiate dual PDE3/PDE4 inhibition from other phosphodiesterase target profiles.','OHTUVAYRE- ensifentrine suspension','e6433c98-41a0-4f99-8f7f-d0e9db6e3f40','12.1 Mechanism of Action','B','PDE4 inhibition alone is familiar in pulmonary pharmacology, but the named agent directly inhibits both PDE3 and PDE4.')
 repl[1440]=make(1440,'donanemab-azbt','Behavioral Health & Nervous Systems/Special Senses',['Pharmacology','Immunology'],'A monoclonal antibody binds an insoluble, N-terminally truncated pyroglutamate-containing form of amyloid beta in brain tissue. Serial amyloid PET demonstrates a reduction in plaque burden.','Which target is directly recognized by this antibody?',{'A':'Soluble monomeric tau','B':'Alpha-synuclein fibrils','C':'BACE1 catalytic site','D':'Soluble amyloid-beta monomers lacking pyroglutamate modification','E':'Insoluble N-truncated pyroglutamate amyloid beta'},'E','Antibody targeting insoluble N-truncated pyroglutamate amyloid beta','Donanemab-azbt is a humanized IgG1 monoclonal antibody directed against insoluble N-truncated pyroglutamate amyloid beta and reduces amyloid-beta plaques.',{'A':'Tau is a different protein target.','B':'Alpha-synuclein is not the documented antigen.','C':'BACE1 inhibition would reduce amyloid generation enzymatically rather than bind existing plaque antigen.','D':'The labeled antibody target is the insoluble N-truncated pyroglutamate form rather than generic soluble monomer.','E':'Correct. Donanemab recognizes insoluble N-truncated pyroglutamate amyloid beta.'},'Distinguish direct recognition of a plaque-associated amyloid-beta species from inhibition of amyloid production.','KISUNLA- donanemab-azbt injection, solution','190352d4-ef62-4679-b4fa-e846e2766afa','12.1 Mechanism of Action','C','Both BACE1 inhibition and anti-amyloid antibodies can reduce amyloid pathology, but direct binding to an insoluble pyroglutamate antigen identifies donanemab.')
 repl[1443]=make(1443,'atogepant','Behavioral Health & Nervous Systems/Special Senses',['Pharmacology','Physiology'],'Trigeminal sensory neurons are exposed to atogepant. A fixed concentration of CGRP produces less receptor-mediated signaling, while serotonin and adrenergic receptor assays are unchanged.','Which direct action best explains the result?',{'A':'Agonism of serotonin 5-HT1B/1D receptors','B':'Inhibition of cyclooxygenase-2','C':'Antagonism of the CGRP receptor','D':'Blockade of voltage-gated sodium channels','E':'Antagonism of beta-adrenergic receptors'},'C','CGRP receptor antagonism','Atogepant is a calcitonin gene-related peptide receptor antagonist; blocking the CGRP receptor reduces CGRP-mediated signaling.',{'A':'Triptan-like 5-HT1B/1D agonism is a different antimigraine mechanism.','B':'COX-2 inhibition does not directly block CGRP receptor signaling.','C':'Correct. Atogepant directly antagonizes the CGRP receptor.','D':'Sodium-channel blockade would affect excitability broadly rather than selectively block fixed-ligand CGRP signaling.','E':'Beta-adrenergic antagonism does not match the receptor-specific assay.'},'Identify CGRP-receptor antagonism from selective blockade of CGRP signaling.','QULIPTA- atogepant tablet','8c8ab8f4-32bd-497a-befa-70c8a51d8d52','12.1 Mechanism of Action','A','Serotonergic agonists are also used in migraine, but the fixed-CGRP receptor assay specifically localizes the effect to CGRP receptor antagonism.')
 for q,v in repl.items(): xs[q].clear(); xs[q].update(v)
 assert ''.join(x['item']['intended_key'] for x in b['items'])==b['answer_key_sequence']
 b.setdefault('schema_repair',{}).setdefault('changes',[]).append('2026-09-10 cross-workstream repair: Q1434, Q1435, Q1440, Q1443 replaced with unique mechanisms after aggregate collision inventory.')
 P.write_text(json.dumps(b,indent=2,ensure_ascii=False)+'\n'); print(json.dumps({'replaced':sorted(repl),'status':'PASS'}))
if __name__=='__main__': main()
